        v = f[:-4]
        kws[v] = open(f"{capdir}/kw/{f}","rb").read()

flags = {}
for f in os.listdir(f"{capdir}/flag"):
    if f.endswith(".out"):
        v = f[:-4]
        flags[v] = open(f"{capdir}/flag/{f}","rb").read()

# Also need funcs-in-class? Capture those outputs for each class
# List classes
