        out.write(f"  {k!r}: {esc(v)},\n")
    out.write("}\n\n")
    out.write("HELP_FUNC = {\n")
    for k,v in sorted(funcs.items()):
        out.write(f"  {k!r}: {esc(v)},\n")
    out.write("}\n\n")
    out.write("HELP_KW = {\n")
    for k,v in sorted(kws.items()):
        out.write(f"  {k!r}: {esc(v)},\n")
    out.write("}\n\n")
    out.write("HELP_FLAG = {\n")
    for k,v in sorted(flags.items()):
        out.write(f"  {k!r}: {esc(v)},\n")
    out.write("}\n\n")

print(f"wrote {outpath} size {os.path.getsize(outpath)}")
