    kw_matched = []
    for k in kw_list:
        if term in k:
            txt = helpdata.HELP_KW.get(k, "")
            out_parts.append(txt)
            kw_matched.append(k)
    # Trailer if no verb/func/kw matches (flags don't count)
    if not verb_matched and not func_matched and not kw_matched:
        out_parts.append(f'No help found for "{term}". See also \'mlr help topics\'.\n')
    return "".join(out_parts)

