def apply_flags_list(opts, flag_list, is_mlrrc=False):
    # Apply list of flags (from mlrrc) sequentially. flag_list is flat list like ["--csv", "--fs", "tab", ...]
    # For mlrrc, each line was split into flag + args, flattened. Need to parse similarly to global flags (without verbs, without immediate?).
    # Immediate flags in mlrrc? Probably allowed? e.g., mlrrc with --version? Unlikely. We'll ignore immediate in mlrrc (just apply as normal?).
    # Also, mlrrc cannot contain --prepipe/--prepipex (error?). Help says allowed at command line, but not in mlrrc to avoid code exec. What error if present? Probably usage error. We'll implement check.
    i=0
    while i < len(flag_list):
        tok = flag_list[i]
        if tok in ("--prepipe", "--prepipex") and is_mlrrc:
            return (f'mlr: option "{tok}" not allowed in .mlrrc file (to avoid unexpected code execution).\nPlease run "mlr --help" for detailed usage information.\n', 1)
        if tok in NEEDS_ARG_FLAGS:
            if i+1 >= len(flag_list):
                return (f'mlr: option "{tok}" missing argument(s).\nPlease run "mlr --help" for detailed usage information.\n', 1)
            val = flag_list[i+1]
            err = apply_flag_with_arg(opts, tok, val)
            if err:
                return err
            i+=2
        elif tok in VALID_FLAGS:
            # Skip immediate flags? For mlrrc, --list-color-codes etc. shouldn't cause immediate exit? Probably just set? But they are immediate. We'll treat as no-op in mlrrc (ignore).
            if tok in ("--list-color-codes", "--list-color-names"):
                i+=1
                continue
            err = apply_flag_no_arg(opts, tok)
            if err:
                return err
            i+=1
        elif tok in ("--cpuprofile",):
            # Needs arg
            if i+1 >= len(flag_list):
                return (f'mlr: option "{tok}" missing argument(s).\nPlease run "mlr --help" for detailed usage information.\n', 1)
            # Ignore (profiling)
            i+=2
        elif tok in ("--traceprofile",):
            i+=1
        elif tok in ("--norc", "--help", "--version", "-h", "-g", "-l", "-L", "-f", "-F", "-k", "-K"):
            # In mlrrc, ignore? Or error? For --norc in mlrrc, probably allowed? But has_norc already handled. Ignore.
            i+=1
        else:
            # Unrecognized in mlrrc: abort with usage? Help says "If there are syntax errors, they abort mlr with a usage message (as if you had mistyped something on the command line)."
            # So return same error as command line.
            return (f'mlr: option "{tok}" not recognized.\nPlease run "mlr --help" for usage information.\n', 1)
    return None

