# --- Typing funcs is_* ---
def _is_handler(name, check):
    @dsl_func(name)
    def _f(args, record, meta, env, gopts, ctx):
        if len(args) != 1:
            return MValue('error', f'{name} expects 1 arg')
        return MValue('bool', check(args[0]))
    return _f

