def _f_jsonparse(args, record, meta, env, gopts, ctx):
    if len(args) != 1:
        return MValue('error', 'json_parse expects 1 arg')
    a = args[0]
    s = a.to_string()
    try:
        import json as _j
        j = _j.loads(s)
        # Convert to MValue recursively (like read_json helper, but without orig preservation? For json_parse, numbers from JSON string: ints/floats? Preserve? For simplicity, no orig (format).
        def conv(x):
            if x is None:
                return MValue('null', None)
            elif isinstance(x, bool):
                return MValue('bool', x)
            elif isinstance(x, int):
                return MValue('int', x)
            elif isinstance(x, float):
                return MValue('float', x)
            elif isinstance(x, str):
                return MValue('str', x)
            elif isinstance(x, list):
                return MValue('array', [conv(e) for e in x])
            elif isinstance(x, dict):
                d = OrderedDict()
                for k,v in x.items():
                    d[k] = conv(v)
                return MValue('map', d)
            else:
