                lines.append(f"{closing}}}")
                return "\n".join(lines)
        elif mv.typ == 'array':
            if len(mv.val)==0:
                return "[]"
            if not pretty:
                return "[" + ", ".join(fmt(v, level+1) for v in mv.val) + "]"
            else:
