def dsl_do_print(exprs, record, meta, env, global_opts, ctx, kind='print', redir=None):
    # print/printn/eprint/eprintn: print expr values to stdout/stderr (direct, not as records).
    # With no args? Probably print newline? Or nothing? For `print` with no args, what? Probably newline? Good.
    # With args: print space-separated? Or comma-separated? Probably space-separated stringified values? With newline for print/eprint, without for printn/eprintn? Good.
    # Redirection (>, >>, |): ignore for now (always to stdout/stderr).
    import sys as _sys
    is_stderr = kind in ('eprint','eprintn')
    add_nl = kind in ('print','eprint')
    fh = _sys.stderr if is_stderr else _sys.stdout
    if not exprs:
        if add_nl:
            fh.write("\n")
        fh.flush()
        return
    vals = [dsl_eval_expr(e, record, meta, env, global_opts, ctx) for e in exprs]
    # Stringify each via to_string? For strings, raw? For numbers with orig? Preserve? Probably to_string (preserves orig). Good.
    # Join with space? Or empty? Probably space? Let's use space.
    # What about maps/arrays? to_string JSON-dumps. Good.
    strs = [v.to_string() for v in vals]
    # Substitute captures? If strings contain \1 and captures available, substitute? Probably (like assignment). Good (use dsl_subst_captures_mv for each? Actually vals already evaluated (strings with \1 preserved, not substituted). Need to substitute now with captures? Good.
    # For print after =~, `print "left_\1"` should show capture. Good (substitute).
    subbed = []
    for v, s in zip(vals, strs):
        if v.typ == 'str' and '\\' in s and env.regex_captures:
            # Substitute \1..\9
            import re as _re
            def repl(m):
                d = m.group(1)
                return env.regex_captures.get(d, "")
            s = _re.sub(r'\\([1-9])', repl, s)
        subbed.append(s)
    out = " ".join(subbed)
    if add_nl:
        out += "\n"
    fh.write(out)
    fh.flush()

def dsl_do_unset(lval, record, meta, env, global_opts, ctx):
    # Unset field/var/map key/array element?
    _, kind, base, indices = lval
    if kind == 'field':
        name = base
        if not indices:
            if name in record:
                del record[name]
        else:
            # Unset nested: e.g., unset $a["k"] (remove key k from map $a)? Or $a[1] (remove array element?)? Implement.
            if name not in record:
                return
            mv = record[name]
            # Traverse to parent of final (all but last indices)
            cur = mv
            for idx_expr in indices[:-1]:
                idx_val = dsl_eval_expr(idx_expr, record, meta, env, global_opts, ctx)
                cur = dsl_index_access(cur, idx_val)
                if cur.typ in ('absent','error'):
                    return
            last_idx_val = dsl_eval_expr(indices[-1], record, meta, env, global_opts, ctx)
            if cur.typ == 'map':
                if last_idx_val.typ in ('absent','error'):
                    return
                key = last_idx_val.to_string()
                if key in cur.val:
                    del cur.val[key]
            elif cur.typ == 'array':
                try:
                    n = int(last_idx_val.to_string())
                except:
                    return
                if 1 <= n <= len(cur.val):
                    del cur.val[n-1]
            else:
                return
    elif kind == 'field_ind':
        name_val = dsl_eval_expr(base, record, meta, env, global_opts, ctx)
        if name_val.typ in ('absent','error'):
            return
        name = name_val.to_string()
